      "Next": "UpdateRoute53"
    },
    "UpdateRoute53": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:DR-UpdateFailover",
      "Next": "ValidateHealth"
    },
    "ValidateHealth": {
      "Type": "Task",
